mermaid:
classDiagram
    class Creator {
        +factoryMethod() Product
        +operation()
    }
    class ConcreteCreator {
        +factoryMethod() Product
    }
    class Product
    class ConcreteProduct
    Creator <|-- ConcreteCreator
    Product <|-- ConcreteProduct
    ConcreteCreator ..> ConcreteProduct : creates

classDiagram
    class Subject {
        +attach(o: Observer)
        +detach(o: Observer)
        +notify()
    }
    class Observer {
        +update()
    }
    Subject o--> Observer : notifies

classDiagram
    class Context {
        -strategy: Strategy
        +execute()
    }
    class Strategy {
        +algorithm()
    }
    class ConcreteStrategyA
    class ConcreteStrategyB
    Context o--> Strategy
    Strategy <|-- ConcreteStrategyA
    Strategy <|-- ConcreteStrategyB

classDiagram
    class Target {
        +request()
    }
    class Adapter {
        +request()
    }
    class Adaptee {
        +specificRequest()
    }
    Target <|.. Adapter
    Adapter --> Adaptee : delegates
